use strict;
use warnings;
use File::Find;

my $repo = "/bench/repo";
my @entities = qw(
  Attachment IdentityProvider Inbox InstanceSetting Memo MemoRelation
  MemoShare Reaction User UserIdentity UserSetting AuthenticationConfigState
);

my @go_files;
find({
  wanted => sub {
    return unless /\.go$/;
    my $full = $File::Find::name;
    my $rel = $full;
    $rel =~ s{^\Q$repo\E/?}{};
    return if $rel =~ m{^\.git/};
    return if $rel =~ m{^store(/|$)};
    push @go_files, $full;
  },
  no_chdir => 1,
}, $repo);

print "Files outside store/: ", scalar(@go_files), "\n";

my %results;
my %file_hits;
for my $e (@entities) {
  $results{$e} = {};
  $file_hits{$e} = [];
}

for my $path (@go_files) {
  open my $fh, "<", $path or die $!;
  my $content = do { local $/; <$fh> };
  close $fh;

  my %aliases;
  while ($content =~ /^\s*(?:(\w+)\s+)?"github.com\/usememos\/memos\/store"/mg) {
    my $alias = $1;
    if (!defined $alias) { $aliases{"store"} = 1; }
    elsif ($alias eq ".") { $aliases{"."} = 1; }
    elsif ($alias eq "_") { next; }
    else { $aliases{$alias} = 1; }
  }
  $aliases{"store"} = 1 unless keys %aliases;

  my $pkg = $path;
  $pkg =~ s{^\Q$repo\E/?}{};
  $pkg =~ s{/[^/]+$}{};

  for my $e (@entities) {
    my $matched = 0;
    for my $alias (keys %aliases) {
      my $pat;
      if ($alias eq ".") {
        $pat = qr/(?<![\w.])\Q$e\E\b/;
      } else {
        $pat = qr/(?<![\w.])\Q$alias\E\.\Q$e\E\b/;
      }
      if ($content =~ $pat) { $matched = 1; last; }
    }
    if ($matched) {
      $results{$e}{$pkg} = 1;
      push @{$file_hits{$e}}, $path;
    }
  }
}

