open my $lf, "<", "/tmp/go_files.txt" or die $!;
my @go_files = grep { chomp; $_ } <$lf>;
close $lf;

print "Files outside store/: ", scalar(@go_files), "\n";

my %results;
my %file_hits;
for my $e (@entities) {
  $results{$e} = {};
  $file_hits{$e} = [];
}

for my $path (@go_files) {
  open my $fh, "<", $path or die "$path: $!";
  my $content = do { local $/; <$fh> };
  close $fh;

  my %aliases;
  while ($content =~ /^\s*(?:(\w+)\s+)?"github.com\/usememos\/memos\/store"/mg) {
    my $alias = $1;
    if (!defined $alias) { $aliases{"store"} = 1; }
    elsif ($alias eq ".") { $aliases{"."} = 1; }
    elsif ($alias eq "_") { next; }
    else { $aliases{$alias} = 1; }
  }
  $aliases{"store"} = 1 unless keys %aliases;

  my $pkg = $path;
  $pkg =~ s{^\Q$repo\E/?}{};
  $pkg =~ s{/[^/]+$}{};

  for my $e (@entities) {
    my $matched = 0;
    for my $alias (keys %aliases) {
      my $pat;
      if ($alias eq ".") {
        $pat = qr/(?<![\w.])\Q$e\E\b/;
      } else {
        $pat = qr/(?<![\w.])\Q$alias\E\.\Q$e\E\b/;
      }
      if ($content =~ $pat) { $matched = 1; last; }
    }
    if ($matched) {
      $results{$e}{$pkg} = 1;
      push @{$file_hits{$e}}, $path;
    }
  }
}

print "\n=== Package counts (outside store/) ===\n";
my @ranked = sort { keys(%{$results{$b}}) <=> keys(%{$results{$a}}) || $a cmp $b } @entities;
for my $e (@ranked) {
  my @pkgs = sort keys %{$results{$e}};
  print "$e: ", scalar(@pkgs), " packages -> ", join(", ", @pkgs), "\n";
}

print "\n=== File hits ===\n";
for my $e (@ranked) {
  print "\n$e (", scalar(@{$file_hits{$e}}), " files):\n";
  for my $p (sort @{$file_hits{$e}}) {
    my $rel = $p; $rel =~ s{^\Q$repo\E/?}{};
    print "  $rel\n";
  }
}
'

