  for my $e (@bases) {
    # match store.X where X is Entity or FindEntity or UpdateEntity or DeleteEntity
    if ($content =~ /(?<![\w.])store\.(?:Find|Update|Delete)?\Q$e\E\b/) {
      $results{$e}{$pkg} = 1;
    }
  }
}

